
import json

def rpa_func(param):
    import re
    def bounds_to_coordinates(bounds):
        """
        将bounds字符串转换为坐标点
        code: 0:成功  1是失败  2：结束流程
        """
        numbers = list(map(int, re.findall(r'\d+', bounds)))

        # 检查是否提取到了4个数字
        if len(numbers) != 4:
            return None
        # 构建字典
        result = {
            "x1": numbers[0],
            "y1": numbers[1],
            "x2": numbers[2],
            "y2": numbers[3]
        }
        return result

    def find_first_input_box_after_special_plate(xml_content):
        """
        在 XML 布局中查找“特殊车牌（港澳本土牌）”下方的第一个车牌输入框（TextView）。

        Args:
            xml_content (str): XML 布局字符串

        Returns:
            dict or None: 返回第一个输入框的属性字典，如 bounds、text 等；若未找到返回 None
        """
        import xml.etree.ElementTree as ET
        root = ET.fromstring(xml_content)

        # 查找文本为“特殊车牌（港澳本土牌）”的 TextView 节点
        target_text = "特殊车牌（港澳本土牌）"
        special_plate_node = None
        for node in root.iter():
            if node.get("text") == target_text and node.get("class") == "android.widget.TextView":
                special_plate_node = node
                break

        if special_plate_node is None:
            return None

        # 获取父节点
        parent = special_plate_node.find('..')  # 注意：ET 不直接支持 '..'，需换方式

        # 更可靠的方式：遍历所有节点，找到 parent
        def find_parent(root, child):
            for elem in root.iter():
                for subelem in elem:
                    if subelem is child:
                        return elem
            return None

        parent = find_parent(root, special_plate_node)
        if parent is None:
            return None

        # 获取该节点在父节点中的索引
        siblings = list(parent)
        try:
            idx = siblings.index(special_plate_node)
        except ValueError:
            return None

        # 从下一个节点开始查找第一个包含 TextView 的 View（模拟输入框）
        for i in range(idx + 1, len(siblings)):
            sibling = siblings[i]
            # 跳过非 View 容器（我们期望的是 android.view.View 包含 TextView）
            if sibling.get("class") == "android.view.View":
                # 查找其内部的 TextView
                inner_textview = sibling.find(".//*[@class='android.widget.TextView']")
                if inner_textview is not None:
                    # 返回该 TextView 的属性
                    return inner_textview.get("bounds")
            # 也考虑直接是 TextView 的情况（虽然当前结构不是）
            elif sibling.get("class") == "android.widget.TextView":
                return sibling.get("bounds")

        return None

    xml = param.get("xml")
    query = param.get("query")
    confirm_text = param.get("confirm_text")
    plate_province_bounds_pattern = r'<node[^>]*text="([京津冀晋蒙辽吉黑沪苏浙皖闽赣鲁豫鄂湘粤桂琼渝川黔云藏陕甘青宁新])"[^>]*bounds="([^"]+)"'
    plate_province_bounds_match = re.search(plate_province_bounds_pattern, xml)
    province = plate_province_bounds_match.group(1) if plate_province_bounds_match else ""

    button_bounds_pattern = r'<node[^>]*text="查询缴费"[^>]*bounds="([^"]+)"'
    button_bounds_match = re.search(button_bounds_pattern, xml)
    button_bounds = button_bounds_match.group(1) if button_bounds_match else ""
    coordinates = bounds_to_coordinates(button_bounds)

    if province == "":
        #省份为空说明还没输车牌，且键盘还未展示，这时应先点击省份输入框
        province_input_box_bounds = find_first_input_box_after_special_plate(xml)
        if province_input_box_bounds is None:
            return {"code": 1}
        else:
            return {
                "code": 0,
                "thought": f"当前页面上车牌输入键盘还未出现，下一步应该点击省份输入框进行省份的输入。",
                "actions": [{
                    "action": "click",
                    "name": "省份输入框",
                    "coordinates": bounds_to_coordinates(province_input_box_bounds),
                }],
                "task_status": "车牌号输入"
            }

    if coordinates is None:
        return {"code": 1}
    else:
        return {
            "code": 0,
            "thought": f"上一步已经完成了车牌的输入，页面上有“查询缴费”按钮，应该点击这个按钮进行查询操作。",
            "actions": [{
                "action": "click",
                "name": "查询缴费",
                "coordinates": coordinates,
            }],
            "task_status": "订单信息查询"
        }

